"use client";

import { useExwave, usePasswordReset } from "@exwave-nexus/auth/react";
import { type ComponentProps, type FormEvent, useId, useState } from "react";
import { AuthLink } from "@/components/exwave/auth-link";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { cn } from "@/lib/utils";

export function ForgotPasswordForm({
  className,
  ...props
}: ComponentProps<"div">) {
  const id = useId();
  const { paths } = useExwave();
  const { request } = usePasswordReset();
  const [email, setEmail] = useState("");

  async function onSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    await request.run(email);
  }

  return (
    <div className={cn("flex flex-col gap-6", className)} {...props}>
      <Card>
        <CardHeader>
          <CardTitle className="text-2xl">
            {request.sent ? "Check your email" : "Reset your password"}
          </CardTitle>
          <CardDescription>
            {request.sent
              ? `If an account uses ${email}, we sent it a link to choose a new password.`
              : "Enter your email and we'll send you a link to choose a new password."}
          </CardDescription>
        </CardHeader>
        {!request.sent && (
          <CardContent>
            <form onSubmit={onSubmit} aria-busy={request.pending}>
              <div className="flex flex-col gap-6">
                <div className="grid gap-2">
                  <Label htmlFor={`${id}-email`}>Email</Label>
                  <Input
                    id={`${id}-email`}
                    type="email"
                    autoComplete="email"
                    value={email}
                    onChange={(event) => setEmail(event.target.value)}
                    required
                  />
                </div>
                {request.message && (
                  <p role="alert" className="text-sm text-destructive">
                    {request.message}
                  </p>
                )}
                <Button
                  type="submit"
                  className="w-full"
                  disabled={request.pending}
                >
                  {request.pending ? "Sending…" : "Send the link"}
                </Button>
              </div>
              <p className="mt-4 text-center text-sm">
                Remembered it?{" "}
                <AuthLink
                  href={paths.signIn}
                  className="underline underline-offset-4"
                >
                  Sign in
                </AuthLink>
              </p>
            </form>
          </CardContent>
        )}
      </Card>
    </div>
  );
}

"use client";

import { useExwave } from "@exwave-nexus/auth/react";
import type { ComponentProps, MouseEvent } from "react";

/** A link between auth pages that moves the way your app does (the provider's `navigate`). */
export function AuthLink({
  href,
  onClick,
  ...props
}: ComponentProps<"a"> & { href: string }) {
  const { navigate } = useExwave();
  const follow = (event: MouseEvent<HTMLAnchorElement>) => {
    onClick?.(event);
    if (
      event.defaultPrevented ||
      event.button !== 0 ||
      event.metaKey ||
      event.ctrlKey ||
      event.shiftKey ||
      event.altKey ||
      props.target
    )
      return;
    event.preventDefault();
    navigate(href);
  };
  return <a href={href} onClick={follow} {...props} />;
}

/** `?redirect=/path` from the address bar when it stays on this site, else `fallback`. */
export function redirectTarget(fallback: string): string {
  if (typeof location === "undefined") return fallback;
  const to = new URLSearchParams(location.search).get("redirect");
  return to?.startsWith("/") && !to.startsWith("//") && !to.startsWith("/\\")
    ? to
    : fallback;
}
